using System.Windows;using System.Windows.Controls;using DirectorFamilyTravelDesk.Models;namespace DirectorFamilyTravelDesk.Views;public partial class TravellersView:UserControl,IRefreshable{private long _id;public TravellersView(){InitializeComponent();}public void RefreshData(){Grid.ItemsSource=App.Repository.GetTravellers(false);}private void Grid_SelectionChanged(object s,SelectionChangedEventArgs e){if(Grid.SelectedItem is TravellerItem x){_id=x.Id;CodeBox.Text=x.ShortCode;FullBox.Text=x.FullName;GroupBox.Text=x.RelationGroup;ActiveBox.IsChecked=x.IsActive;}}private void Save_Click(object s,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(CodeBox.Text)){MessageBox.Show("Short form is required.");return;}try{App.Repository.SaveTraveller(new(){Id=_id,ShortCode=CodeBox.Text,FullName=FullBox.Text,RelationGroup=GroupBox.Text,IsActive=ActiveBox.IsChecked==true});_id=0;CodeBox.Text=FullBox.Text="";GroupBox.Text="Family";ActiveBox.IsChecked=true;RefreshData();}catch(Exception ex){MessageBox.Show(ex.Message);}}}